pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // restrict lengths to be equal and >0 per contract requirements
        // also restrict v[i] to avoid overflow in multiplication on any element
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        for (uint i = 0; i < v.length; i++) {
            // require condition: v[i]==0 OR (v[i]*1e18/v[i] == 1e18)
            // this condition prevents overflow during multiplication in the loop
            // we mirror it exactly to stay in the admissible domain
            vm.assume(v[i] == 0 || ((v[i] * 1000000000000000000) / v[i]) == 1000000000000000000);
        }
        // prank the required msg.sender and call transfer
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // use try/catch to capture whether call reverted
        bool ok;
        try c.transfer(_tos, v) returns (bool result) {
            // call succeeded, assert result is true
            assertTrue(result);
        } catch {
            // revert cases are not considered; we only assert when call doesn't revert
        }
    }
}

